package ais.action.master.sosial.helper;
import ais.common.Common; import ais.database.model.*;
public final class SocialPrivilegeGuard { public static final String VIEW="VIEW",OPERATE="OPERATE",APPROVE="APPROVE",FINANCE="FINANCE",AUDIT="AUDIT",ADMIN="ADMIN"; public void require(SocialRequestContext c,String capability){if(c==null||!c.isAuthenticated())throw new SecurityException("Login diperlukan.");try{if(Common.getApakahAdmin())return;}catch(Exception ignored){}String allowed=config("sosial_roles_"+capability.toLowerCase());for(Tbmrole role:c.getUser().ambilRoles()){if(role!=null&&contains(allowed,role.getRoleId()))return;}throw new SecurityException("Hak akses Sosial tidak mencukupi.");} private String config(String k){try{return Common.getKonfigurasi(k,"").getNilai();}catch(Exception e){return "";}} private boolean contains(String csv,String v){if(v==null)return false;for(String x:csv.split(","))if(v.equalsIgnoreCase(x.trim()))return true;return false;} }
